import { LitElement, css, html } from "lit";

const splitList = (value) => {
  if (Array.isArray(value)) return value.map(String).map((item) => item.trim()).filter(Boolean);
  return String(value ?? "").split(",").map((item) => item.trim()).filter(Boolean);
};

const booleanValue = (value) => value === true || value === "" || value === "true" || value === "1";

const labels = {
  name: "Name",
  lastName: "Last name",
  email: "Email",
  phone: "Phone",
  address: "Address",
  service: "Select a service",
  contact: "Preferred contact method",
  message: "How can we help?",
  send: "Send message",
  sending: "Sending...",
  phoneOption: "Phone",
  emailOption: "Email",
  smsOption: "SMS",
  success: "Thanks! Your message was sent successfully.",
  error: "We could not send your message. Please try again.",
  configurationError: "The contact form is not configured correctly.",
  subject: "New Service Request",
  noMessage: "No additional information",
};

export class FormContact extends LitElement {
  static properties = {
    to: { converter: { fromAttribute: splitList } },
    services: { converter: { fromAttribute: splitList } },
    server: { type: String },
    img: { type: String },
    emailcolor: { type: String },
    isenglish: { converter: { fromAttribute: booleanValue } },
    timeout: { type: Number },
    loading: { state: true },
    status: { state: true },
    message: { state: true },
    canSubmit: { state: true },
  };

  constructor() {
    super();
    this.to = [];
    this.services = [];
    this.server = "";
    this.img = "";
    this.emailcolor = "1";
    this.isenglish = false;
    this.timeout = 15000;
    this.loading = false;
    this.status = "idle";
    this.message = "";
    this.canSubmit = false;
  }

  updated(changed) {
    // JSX frameworks often assign arrays/booleans as properties instead of attributes.
    if (changed.has("to") && !Array.isArray(this.to)) this.to = splitList(this.to);
    if (changed.has("services") && !Array.isArray(this.services)) this.services = splitList(this.services);
    if (changed.has("isenglish") && typeof this.isenglish !== "boolean") {
      this.isenglish = booleanValue(this.isenglish);
    }
  }

  isFormComplete(form) {
    const requiredFields = [...form.querySelectorAll("[required]")]
      .filter((field) => field.type !== "radio");
    return form.checkValidity() && requiredFields.every((field) => String(field.value).trim() !== "");
  }

  updateValidity(event) {
    this.canSubmit = this.isFormComplete(event.currentTarget);
    if (this.status !== "idle") {
      this.status = "idle";
      this.message = "";
    }
  }

  async handleSubmit(event) {
    event.preventDefault();
    if (this.loading) return;

    const form = event.currentTarget;
    if (!this.isFormComplete(form)) {
      form.reportValidity();
      this.canSubmit = false;
      return;
    }
    const recipients = splitList(this.to);
    if (!this.server || recipients.length === 0) {
      this.showError(new Error("Missing server or recipients"), labels.configurationError);
      return;
    }

    const data = Object.fromEntries(new FormData(form));
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), Math.max(1000, this.timeout));
    this.loading = true;
    this.status = "idle";
    this.message = "";

    try {
      const requests = recipients.map(async (toEmail) => {
        const payload = {
          toEmail,
          nombre: data.name,
          lastname: data.lastName,
          email: data.email,
          asunto: `${labels.subject} From ${data.name} ${data.lastName}`,
          phone: data.phone,
          address: data.address,
          service: data.services,
          mensaje: data.message?.trim() || labels.noMessage,
          img: this.img,
          color: this.emailcolor,
          waytocontact: data.contact,
        };

        const response = await fetch(this.server, {
          method: "POST",
          headers: { Accept: "application/json", "Content-Type": "application/json" },
          body: JSON.stringify(payload),
          signal: controller.signal,
        });
        if (!response.ok) throw new Error(`Email server returned ${response.status}`);
        return payload;
      });

      const payloads = await Promise.all(requests);
      form.reset();
      this.canSubmit = false;
      this.status = "success";
      this.message = labels.success;
      this.dispatchEvent(new CustomEvent("form-contact-success", {
        detail: { payloads }, bubbles: true, composed: true,
      }));
    } catch (error) {
      this.showError(error, labels.error);
    } finally {
      clearTimeout(timeoutId);
      this.loading = false;
    }
  }

  showError(error, message) {
    this.status = "error";
    this.message = message;
    this.dispatchEvent(new CustomEvent("form-contact-error", {
      detail: { error }, bubbles: true, composed: true,
    }));
  }

  render() {
    const t = labels;
    return html`
      <form part="form" @submit=${this.handleSubmit} @input=${this.updateValidity} @change=${this.updateValidity}>
        <div part="fields" class="fields">
          ${this.input("name", t.name, "text", "given-name")}
          ${this.input("lastName", t.lastName, "text", "family-name")}
          ${this.input("email", t.email, "email", "email")}
          ${this.input("phone", t.phone, "tel", "tel")}
          ${this.input("address", t.address, "text", "street-address")}
          <label part="field service-field">
            <span part="label">${t.service}</span>
            <select part="control select" name="services" required>
              <option value="" selected disabled>${t.service}</option>
              ${this.services.map((service) => html`<option value=${service}>${service}</option>`)}
            </select>
          </label>
        </div>

        <fieldset part="contact-methods">
          <legend part="legend">${t.contact}</legend>
          ${this.radio("phone", t.phoneOption, true)}
          ${this.radio("email", t.emailOption)}
          ${this.radio("sms", t.smsOption)}
        </fieldset>

        <label part="field message-field" class="message-field">
          <span part="label">${t.message}</span>
          <textarea part="control textarea" name="message" rows="4" placeholder="Tell us a little about your project or request" required></textarea>
        </label>

        <button part="submit" type="submit" ?disabled=${this.loading || !this.canSubmit}>
          ${this.loading ? html`<span class="spinner" aria-hidden="true"></span>${t.sending}` : html`${t.send}<span class="arrow" aria-hidden="true">→</span>`}
        </button>
        ${this.status !== "idle" ? html`
          <div part="status ${this.status}" class="status ${this.status}" role=${this.status === "error" ? "alert" : "status"} aria-live="polite">
            <span class="status-icon" aria-hidden="true">${this.status === "success" ? "✓" : "!"}</span>
            <span>${this.message}</span>
          </div>
        ` : ""}
      </form>
    `;
  }

  input(name, label, type, autocomplete) {
    return html`<label part="field ${name}-field"><span part="label">${label}</span><input part="control input" name=${name} type=${type} autocomplete=${autocomplete} placeholder=${label} required /></label>`;
  }

  radio(value, label, checked = false) {
    return html`<label part="radio-option" class="radio"><input part="radio" type="radio" name="contact" value=${value} .checked=${checked} required /><span part="radio-label">${label}</span></label>`;
  }

  static styles = css`
    :host {
      --fc-accent: #4f46e5;
      --fc-accent-hover: #4338ca;
      --fc-accent-soft: #eef2ff;
      --fc-surface: #ffffff;
      --fc-text: #172033;
      --fc-muted: #64748b;
      --fc-border: #d8dee9;
      --fc-radius: 12px;
      --fc-success: #15803d;
      --fc-success-soft: #f0fdf4;
      --fc-error: #b42318;
      --fc-error-soft: #fff1f0;
      display: block;
      color: var(--fc-text);
      font: inherit;
      container-type: inline-size;
    }
    * { box-sizing: border-box; }
    form { display: grid; gap: 1.25rem; margin: 0; }
    .fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--form-gap, 1rem); }
    label { display: grid; gap: .45rem; min-width: 0; }
    label > span, legend { color: var(--fc-text); font-size: .875rem; font-weight: 650; letter-spacing: -.01em; }
    input, select, textarea, button { max-width: 100%; font: inherit; color: inherit; }
    input, select, textarea {
      width: 100%; border: 1px solid var(--fc-border); border-radius: var(--fc-radius);
      background: var(--fc-surface); padding: .82rem .9rem; outline: none;
      box-shadow: 0 1px 2px rgb(15 23 42 / 4%);
      transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;
    }
    input:hover, select:hover, textarea:hover { border-color: color-mix(in srgb, var(--fc-accent) 45%, var(--fc-border)); }
    input:focus, select:focus, textarea:focus {
      border-color: var(--fc-accent);
      box-shadow: 0 0 0 3px color-mix(in srgb, var(--fc-accent) 14%, transparent);
    }
    input::placeholder, textarea::placeholder { color: var(--fc-muted); opacity: .75; }
    select { cursor: pointer; }
    textarea { min-height: 8rem; resize: vertical; line-height: 1.5; }
    fieldset {
      display: flex; flex-wrap: wrap; gap: .65rem; border: 0; margin: 0; padding: 0;
    }
    legend { width: 100%; margin-bottom: .45rem; padding: 0; }
    .radio {
      display: flex; align-items: center; grid-template-columns: auto 1fr; gap: .45rem;
      border: 1px solid var(--fc-border); border-radius: 999px; padding: .55rem .8rem;
      background: var(--fc-surface); cursor: pointer; transition: border-color .18s, background .18s;
    }
    .radio:has(input:checked) { border-color: var(--fc-accent); background: var(--fc-accent-soft); }
    .radio input { width: 1rem; height: 1rem; margin: 0; accent-color: var(--fc-accent); }
    .radio span { font-size: .875rem; font-weight: 550; }
    button {
      display: inline-flex; align-items: center; justify-content: center; gap: .6rem; width: 100%;
      min-height: 3.15rem; border: 0; border-radius: var(--fc-radius); padding: .85rem 1.15rem;
      background: var(--fc-accent); color: #fff; font-weight: 700; cursor: pointer;
      box-shadow: 0 8px 20px color-mix(in srgb, var(--fc-accent) 22%, transparent);
      transition: background .18s ease, box-shadow .18s ease, transform .18s ease, opacity .18s ease;
    }
    button:hover:not(:disabled) { background: var(--fc-accent-hover); box-shadow: 0 10px 24px color-mix(in srgb, var(--fc-accent) 30%, transparent); transform: translateY(-1px); }
    button:active:not(:disabled) { transform: translateY(0); }
    button:focus-visible { outline: 3px solid color-mix(in srgb, var(--fc-accent) 25%, transparent); outline-offset: 2px; }
    button:disabled { box-shadow: none; cursor: not-allowed; opacity: .42; }
    .arrow { font-size: 1.2em; transition: transform .18s ease; }
    button:hover:not(:disabled) .arrow { transform: translateX(3px); }
    .spinner { width: 1rem; height: 1rem; border: 2px solid rgb(255 255 255 / 35%); border-top-color: white; border-radius: 50%; animation: spin .7s linear infinite; }
    .status {
      display: flex; align-items: center; gap: .75rem; border: 1px solid; border-radius: var(--fc-radius);
      padding: .9rem 1rem; font-size: .925rem; font-weight: 550;
      animation: reveal .24s ease-out;
    }
    .status-icon { display: grid; flex: 0 0 auto; place-items: center; width: 1.6rem; height: 1.6rem; border-radius: 50%; color: white; font-weight: 800; }
    .success { border-color: color-mix(in srgb, var(--fc-success) 25%, transparent); background: var(--fc-success-soft); color: var(--fc-success); }
    .success .status-icon { background: var(--fc-success); }
    .error { border-color: color-mix(in srgb, var(--fc-error) 25%, transparent); background: var(--fc-error-soft); color: var(--fc-error); }
    .error .status-icon { background: var(--fc-error); }
    @keyframes spin { to { transform: rotate(360deg); } }
    @keyframes reveal { from { opacity: 0; transform: translateY(-4px); } }
    @container (max-width: 36rem) { .fields { grid-template-columns: 1fr; } }
    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; } }
  `;
}

if (!customElements.get("form-contact")) customElements.define("form-contact", FormContact);
